--- a/harness/worker/src/auth.ts
+++ b/harness/worker/src/auth.ts
@@ -1,14 +1,22 @@
-export function check(req: Request, env: Env) {
-  const h = req.headers.get("authorization");
-  return h === "Bearer " + env.MCP_TOKEN;
-}
+const BEARER = "Bearer ";
+
+export function extractToken(req: Request): string | null {
+  const h = req.headers.get("authorization");
+  if (!h || !h.startsWith(BEARER)) return null;
+  return h.slice(BEARER.length);
+}
+
+export function check(req: Request, env: Env): boolean {
+  const t = extractToken(req);
+  return t !== null && t === env.MCP_TOKEN;
+}
+
+export function unauthorized(): Response {
+  return new Response("unauthorized", { status: 401 });
+}
